from collections import deque,Counter

def comps(coords, pred):
 seen=set(); out=[]
 for p in coords:
  if p in seen or not pred(*p): continue
  q=[p];seen.add(p); comp=[]
  while q:
   r,c=q.pop();comp.append((r,c))
   for x in [(r-1,c),(r+1,c),(r,c-1),(r,c+1)]:
    if x in coords and x not in seen and pred(*x):seen.add(x);q.append(x)
  out.append(comp)
 return sorted(out,key=lambda x:min(x))
