@lru_cache(None)
def tile(rem, counts):
 if rem==0:return () if not any(counts) else None
 # pick remaining cell with fewest feasible tile placements
 best_opts=None
 xbits=rem
 while xbits:
  lsb=xbits & -xbits; i=lsb.bit_length()-1; xbits-=lsb
  opts=[]
  for h,w,r,c,b in bycell[i]:
   if b&rem==b:
    di=dims.index((h,w))
    if counts[di]>0:
     opts.append((di,(h,w,r,c,b)))
  if best_opts is None or len(opts)<len(best_opts):
   best_opts=opts
   if len(opts)<=1:break
 if not best_opts:return None
 for di,pl in best_opts:
  newc=list(counts);newc[di]-=1
  sub=tile(rem^pl[4],tuple(newc))
  if sub is not None:return (pl,)+sub
 return None
